// Create a normalized case-insensitive map for instant fast fallback lookups
export const BUILTIN_LOWER_MAP = Object.entries(BUILTIN_DICTIONARY_EN).reduce((acc, [k, v]) => {
  acc[k.toLowerCase().trim().replace(/\s+/g, ' ')] = v;
  return acc;
}, {});

export default BUILTIN_DICTIONARY_EN;
